var t=`0391-gromperekichelcher`;var i=`world-0391`;var n=`LU`;var l=`western-europe`;var r=4;var s=35;var a={en:`Gromperekichelcher`,ua:`Громперекіхельхер`};var u={en:`A traditional Luxembourg dish made with potato, yellow onion, chicken egg, all-purpose flour. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Люксембург. Основні інгредієнти: картопля, жовта цибуля, куряче яйце, пшеничне борошно універсальне. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:10,i:[[`potato`,900,`g`],[`yellow-onion`,120,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`chicken-egg`,2,`pcs`],[`all-purpose-flour`,60,`g`],[`parsley`,16,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 19 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 19 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:19,i:[[`sunflower-oil`,90,`ml`]]}];var d={slug:t,id:i,country:`LU`,region:l,servings:4,minutes:35,title:a,text:u,steps:g};export{n as country,d as default,i as id,s as minutes,l as region,r as servings,t as slug,g as steps,u as text,a as title};